/**
 * Speculative Token & Figure Verifier for MITRA
 *
 * Inspects draft text generated by neural models (Gemini / Grok) and validates
 * that every stated currency figure (₹, INR, numbers) and academic year (e.g., 2026-27)
 * exists within the canonical evidence and database facts.
 *
 * If an unauthorized or hallucinated numerical figure is detected, it flags the draft
 * so MITRA can automatically fall back to the deterministic tabular record.
 */

import { getDb } from './store.js';

export function verifySpeculativeFigures(draftText, canonicalEvidence = []) {
  if (typeof draftText !== 'string' || !draftText.trim()) {
    return { verified: true, extractedFigures: [] };
  }

  // 1. Extract candidate numbers that look like fees, currency, or cutoffs (e.g. 1,05,000, 105000, 17217, 35000)
  const currencyMatches = draftText.match(/(?:₹|rs\.?|inr)?\s*([0-9]{1,3}(?:,[0-9]{2,3})*(?:\.[0-9]+)?|[0-9]{4,7})/gi) || [];
  const normalizedFigures = currencyMatches.map(m => {
    return m.replace(/[^0-9]/g, '');
  }).filter(num => num.length >= 4); // Filter to significant figures (>= 1,000)

  if (!normalizedFigures.length) {
    return { verified: true, extractedFigures: [] };
  }

  // 2. Gather all authorized numbers from retrieved canonical evidence and SQLite facts
  const authorizedNumbers = new Set();

  for (const record of canonicalEvidence) {
    if (record?.facts) {
      extractNumbersFromObject(record.facts, authorizedNumbers);
    }
    if (record?.text) {
      const nums = record.text.match(/[0-9]{4,7}/g) || [];
      nums.forEach(n => authorizedNumbers.add(n));
    }
  }

  // Also include current knowledge facts from db
  const db = getDb();
  if (db?.knowledge) {
    for (const k of db.knowledge) {
      if (k.facts) extractNumbersFromObject(k.facts, authorizedNumbers);
    }
  }

  // Common institutional constants and years
  authorizedNumbers.add('2024');
  authorizedNumbers.add('2025');
  authorizedNumbers.add('2026');
  authorizedNumbers.add('2027');
  authorizedNumbers.add('2028');

  // 3. Verify each extracted figure
  const unauthorized = normalizedFigures.filter(num => !authorizedNumbers.has(num));

  if (unauthorized.length > 0) {
    return {
      verified: false,
      reason: `Unauthorized figures detected in draft: ${unauthorized.join(', ')}`,
      unauthorized,
    };
  }

  return { verified: true, extractedFigures: normalizedFigures };
}

function extractNumbersFromObject(obj, targetSet) {
  if (!obj || typeof obj !== 'object') return;
  for (const val of Object.values(obj)) {
    if (typeof val === 'number') {
      targetSet.add(String(val));
    } else if (typeof val === 'string') {
      const matches = val.match(/[0-9]{4,7}/g);
      if (matches) matches.forEach(m => targetSet.add(m));
    } else if (typeof val === 'object') {
      extractNumbersFromObject(val, targetSet);
    }
  }
}

